/**
 * build_deploy_bundle.js
 *
 * src/*.src.js (저작 소스, lib/*.js를 require) 를 읽어서 lib 모듈 본문을 그 자리에
 * 그대로 스플라이스(inline)하고, require가 전혀 남지 않은 자기완결형 코드를 만들어
 * 대응하는 루트 *_code.js 파일에 덮어쓴다.
 *
 * n8n Function 노드는 실행 시 파일 시스템에 접근할 수 없어 require('./lib/...')가
 * 항상 실패한다 — 그래서 "고치는 곳(src/)"과 "배포하는 곳(루트 *_code.js)"을 분리하고,
 * 빌드 시점에만(=일반 node 프로세스, 파일시스템 접근 가능) 인라이닝한다.
 *
 * 실행: node scripts/build_deploy_bundle.js
 */

const fs = require('fs');
const path = require('path');
const vm = require('vm');
const { execFileSync } = require('child_process');

const ROOT = path.join(__dirname, '..');
const SRC_DIR = path.join(ROOT, 'src');
const LIB_DIR = path.join(ROOT, 'lib');

// src 저작 소스 → 배포 대상 루트 파일 매핑 (리팩토링 계획서 "대상 파일 및 매핑" 참고)
const MANIFEST = [
  { src: 'swing-scanner.src.js', out: 'swing_scanner_code.js' },
  { src: 'weekly-reporter.src.js', out: 'weekly_reporter_code.js' },
  { src: 'risk-blacklist-updater.src.js', out: 'Refresh_Risk_Blacklist_KRX_KIND_code.js' },
  { src: 'theme-blacklist-updater.src.js', out: 'Refresh_Theme_Blacklist_Naver_code.js' },
  { src: 'healthcheck.src.js', out: 'Daily_Healthcheck_code.js' },
  { src: 'daily-position-monitor.src.js', out: 'Daily_Position_Monitor.js' },
];

const REQUIRE_LINE_RE = /^const\s*\{([^}]+)\}\s*=\s*require\(['"]\.\.\/lib\/(\w+)['"]\);?\s*$/;

function readLines(filePath) {
  return fs.readFileSync(filePath, 'utf8').replace(/\r\n/g, '\n').split('\n');
}

// ===== 0. lib 파일 간 최상위 식별자 충돌 사전 점검 =====
function checkLibNameCollisions() {
  const declRe = /^(?:const|let|var|function)\s+(\w+)/;
  const owners = new Map(); // name -> [libFile,...]
  const libFiles = fs.readdirSync(LIB_DIR).filter((f) => f.endsWith('.js') && f !== 'logger.js');

  for (const libFile of libFiles) {
    const lines = readLines(path.join(LIB_DIR, libFile));
    for (const line of lines) {
      if (/^module\.exports\s*=/.test(line)) break; // exports 라인부터는 본문 아님
      const m = line.match(declRe);
      if (m) {
        const name = m[1];
        if (!owners.has(name)) owners.set(name, []);
        owners.get(name).push(libFile);
      }
      // lib 파일 간 상호 require 금지 확인
      if (REQUIRE_LINE_RE.test(line)) {
        throw new Error(`[collision-check] ${libFile}에 다른 lib 모듈을 require하는 줄이 있습니다(lib 간 상호 의존 금지): ${line}`);
      }
    }
  }

  const collisions = [...owners.entries()].filter(([, files]) => new Set(files).size > 1);
  if (collisions.length > 0) {
    const detail = collisions.map(([name, files]) => `  - ${name}: ${[...new Set(files)].join(', ')}`).join('\n');
    throw new Error(`[collision-check] lib 파일 간 최상위 식별자 충돌 발견:\n${detail}`);
  }
}

// ===== 1. src 파일 하나를 스플라이스해서 self-contained 텍스트로 변환 =====
function buildOne(srcFile) {
  const srcPath = path.join(SRC_DIR, srcFile);
  const lines = readLines(srcPath);
  const output = [];

  for (const line of lines) {
    const m = line.match(REQUIRE_LINE_RE);
    if (!m) {
      output.push(line);
      continue;
    }

    const libName = m[2];
    const libPath = path.join(LIB_DIR, `${libName}.js`);
    if (!fs.existsSync(libPath)) {
      throw new Error(`[build:${srcFile}] lib/${libName}.js 를 찾을 수 없습니다 (요청 줄: "${line}")`);
    }
    const libLines = readLines(libPath);
    const cutIndex = libLines.findIndex((l) => /^module\.exports\s*=/.test(l));
    if (cutIndex < 0) {
      throw new Error(`[build:${srcFile}] lib/${libName}.js 에서 "module.exports = ..." 줄을 찾지 못했습니다.`);
    }
    const bodyLines = libLines.slice(0, cutIndex);
    if (bodyLines.some((l) => REQUIRE_LINE_RE.test(l))) {
      throw new Error(`[build:${srcFile}] lib/${libName}.js 본문 안에 다른 lib require가 있습니다(금지).`);
    }
    output.push(...bodyLines);
  }

  const header = `// AUTO-GENERATED by scripts/build_deploy_bundle.js — 이 파일을 직접 고치지 마세요.\n// 수정하려면 src/${srcFile}를 고친 뒤 \`node scripts/build_deploy_bundle.js\`를 다시 실행하세요.\n`;
  return header + output.join('\n');
}

// ===== 2. 문법 검증 =====
// 일부 노드 소스(Theme Blacklist Updater)는 최상위 await를 직접 쓴다 — n8n Function
// 노드는 내부적으로 async 컨텍스트에서 코드를 실행하므로 라이브에서는 정상 동작하지만,
// 일반 `node --check`는 최상위 await를 문법 에러로 거부한다(원본 파일로 직접 확인함).
// 그래서 실제 배포 파일이 아니라 "async 래퍼로 감싼 임시 사본"을 검증한다.
function assertValidSyntax(code, label) {
  const wrapped = `(async function() {\n${code}\n});`;
  const tmpPath = path.join(require('os').tmpdir(), `syntax-check-${label}-${Date.now()}.js`);
  fs.writeFileSync(tmpPath, wrapped, 'utf8');
  try {
    execFileSync(process.execPath, ['--check', tmpPath], { stdio: 'pipe' });
  } finally {
    fs.unlinkSync(tmpPath);
  }
}

// ===== 3. vm 기반 런타임 스모크 테스트 =====
// this.helpers.httpRequest / this.getWorkflowStaticData 를 스텁해서, 생성된 파일이
// "실행은 끝까지 되는지"(구조적으로 안 깨졌는지)만 값싸게 확인한다.
// (diff는 "텍스트가 의도한 대로만 바뀌었는지"를 보고, 이 스모크 테스트는 "그 결과가 실제로
// 예외 없이 실행되는지"를 본다 — 둘 다 필요, 서로 대체 불가)
function smokeTest(code, label) {
  const store = {};
  // 노드 소스 대부분은 `const run = async function(){...}; return run();` 형태다 —
  // run()이 "맨 호출"(bare call)이라 .call(fakeThis)로 바깥 함수에 this를 묶어도
  // 안쪽 run() 호출에는 전달되지 않는다(strict가 아닌 스크립트에서 맨 호출의 this는
  // 전역객체로 귀결됨 — 실제로 vm 테스트로 확인함). n8n 자신도 같은 방식으로 동작하는
  // 것으로 보인다(this.helpers/this.getWorkflowStaticData가 실제로는 실행 컨텍스트의
  // 전역에 노출됨) — 그래서 helpers/getWorkflowStaticData를 sandbox 전역에 직접 둔다.
  // Object.assign({}, global)은 non-enumerable getter로 정의된 전역(Buffer 등)을
  // 빠뜨린다(실제로 겪음) — getOwnPropertyDescriptors로 전체를 복제한다.
  const sandbox = Object.create(null);
  Object.defineProperties(sandbox, Object.getOwnPropertyDescriptors(global));
  Object.assign(sandbox, {
    items: [],
    helpers: {
      httpRequest: async (opts) => (opts && opts.json === false ? '' : []),
    },
    getWorkflowStaticData: () => store,
  });
  vm.createContext(sandbox);

  // async로 감싸는 이유: 저작 소스 중 일부(Theme Blacklist Updater)는
  // `const run = async function(){...}; return run();` 패턴이 아니라 최상위 await를
  // 직접 쓴다 — 두 스타일 모두 async 래퍼 안에서는 동일하게 동작한다.
  const wrapped = `(async function() {\n${code}\n})()`;

  let resultPromise;
  try {
    resultPromise = vm.runInContext(wrapped, sandbox, { timeout: 15000 });
  } catch (e) {
    throw new Error(`[smoke:${label}] vm 실행 중 동기 에러: ${e && e.message}`);
  }

  const timeoutMs = 20000;
  const timeoutPromise = new Promise((_, reject) =>
    setTimeout(() => reject(new Error(`[smoke:${label}] ${timeoutMs}ms 안에 완료되지 않음`)), timeoutMs)
  );

  return Promise.race([Promise.resolve(resultPromise), timeoutPromise]).catch((err) => {
    throw new Error(`[smoke:${label}] 비동기 실행 실패: ${err && err.message}`);
  });
}

async function main() {
  console.log('1) lib 파일 간 이름 충돌 검사...');
  checkLibNameCollisions();
  console.log('   OK\n');

  const results = [];
  for (const { src, out } of MANIFEST) {
    console.log(`2) 빌드: src/${src} -> ${out}`);
    const generated = buildOne(src);
    const outPath = path.join(ROOT, out);

    console.log(`   문법 검증...`);
    assertValidSyntax(generated, out.replace(/[^a-zA-Z0-9._-]/g, '_'));

    fs.writeFileSync(outPath, generated, 'utf8');

    console.log(`   런타임 스모크 테스트...`);
    await smokeTest(generated, out);

    console.log(`   OK (${generated.length.toLocaleString()} bytes)\n`);
    results.push(out);
  }

  console.log(`모든 빌드 완료: ${results.join(', ')}`);
}

main().catch((e) => {
  console.error('\n빌드 실패:', e && e.message);
  process.exit(1);
});
